def _truncate_graph(graph: dict[str, Any]) -> dict[str, Any]:
    nodes = graph["nodes"]

    if len(nodes) <= graph_database.MAX_CUSTOM_QUERY_NODES:
        return graph

    retained_nodes = nodes[: graph_database.MAX_CUSTOM_QUERY_NODES]
    retained_ids = {node["id"] for node in retained_nodes}

    retained_relationships = [
        relationship
        for relationship in graph["relationships"]
        if relationship["source"] in retained_ids
        and relationship["target"] in retained_ids
    ]

    graph["nodes"] = retained_nodes
    graph["relationships"] = retained_relationships
    graph["truncated"] = True
    # `total_nodes` intentionally preserves the pre-truncation count.
